// DBS iBanking Alert - Extract Amount, Date, Recipient
// v2: strips HTML, multiple pattern fallbacks, debug output

function stripHtml(s) {
  return s
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/td>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

const results = [];

for (const item of $input.all()) {
  const subject = item.json.subject || '';
  const plain   = item.json.text    || item.json.snippet || '';
  const html    = item.json.html    || '';

  // Use plain-text body when available; fall back to stripped HTML
  const body    = plain.trim() ? plain : stripHtml(html);
  const content = subject + '\n' + body;

  // ── Amount ──────────────────────────────────────────────────────────────
  let amount = null;
  const amtPatterns = [
    /(?:SGD|S\$)\s*([\d,]+\.\d{2})/i,          // SGD 1,234.56
    /(?:SGD|S\$)\s*([\d,]+)/i,                  // SGD 500
    /amount[:\s]+(?:SGD\s*)?([\d,]+\.?\d*)/i,   // Amount: 99.00
    /of\s+(?:SGD|S\$)\s*([\d,]+\.?\d*)/i,       // of SGD 45.80
    /(?:debit|credit)(?:ed)?[^\d]{0,20}([\d,]+\.\d{2})/i,
  ];
  for (const re of amtPatterns) {
    const m = content.match(re);
    if (m) { amount = parseFloat(m[1].replace(/,/g, '')); break; }
  }

  // ── Date ────────────────────────────────────────────────────────────────
  let txnDate = null;
  const datePatterns = [
    /(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4})/i,  // 28 May 2026
    /(?:date|dated|on)[:\s]+(\d{2}[\/-]\d{2}[\/-]\d{4})/i,                               // Date: 28/05/2026
    /(\d{2}[\/-]\d{2}[\/-]\d{4})/,                                                        // 28/05/2026
    /(\d{4}-\d{2}-\d{2})/,                                                                 // 2026-05-28
    /on\s+(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4})/i,
  ];
  for (const re of datePatterns) {
    const m = content.match(re);
    if (m) { txnDate = m[1].trim(); break; }
  }

  // ── Recipient ────────────────────────────────────────────────────────────
  let recipient = null;
  const recipPatterns = [
    /(?:paid to|transfer(?:red)? to|payment to)[:\s]+([^\n\r<]{2,60}?)(?=\s*(?:\n|\r|<|Ref|Date|Time|Amt|SGD|$))/i,
    /(?:payee|recipient)[:\s]+([^\n\r<]{2,60}?)(?=\s*(?:\n|\r|<|Ref|Date|Time|Amt|SGD|$))/i,
    /\bto[:\s]+([A-Z][^\n\r<,]{2,50}?)(?=\s*(?:\n|\r|<|,|Ref|Date|Time|Amt|SGD|\+65|$))/i,
    /(?:merchant|at)[:\s]+([A-Z0-9][^\n\r<,]{2,50}?)(?=\s*(?:\n|\r|<|,|on|Ref|Date|SGD|$))/i,
  ];
  for (const re of recipPatterns) {
    const m = content.match(re);
    if (m && m[1].trim().length > 1) { recipient = m[1].trim(); break; }
  }

  results.push({
    json: {
      emailId:      item.json.id,
      subject,
      from:         item.json.from,
      emailDate:    item.json.date,
      amount,
      currency:     'SGD',
      txnDate,
      recipient,
      extractionOk: !!(amount && txnDate && recipient),
      _debug: {
        amountFound:    amount    !== null,
        dateFound:      txnDate   !== null,
        recipientFound: recipient !== null,
        // First 500 chars of processed body for troubleshooting
        bodyPreview:    body.substring(0, 500)
      }
    }
  });
}

return results;
